sed -i 's|<PackageVersion Include="xunit" |<PackageVersion Include="NetArchTest.Rules" Version="1.3.2" />\n    &|' Directory.Packages.props &&
sed -i 's|    <Project Path="tests/PaymentAuthorization.UnitTest.*|    <Project Path="tests/PaymentAuthorization.ArchitectureTest/PaymentAuthorization.ArchitectureTest.csproj" />\n&|' PaymentAuthorization.slnx &&
cat > tests/PaymentAuthorization.ArchitectureTest/LayerDependencyTests.cs <<'EOF'
using System.Reflection;
using NetArchTest.Rules;
using PaymentAuthorization.Application;
using PaymentAuthorization.Domain;

namespace PaymentAuthorization.ArchitectureTest;

public class LayerDependencyTests
{
    private const string InfrastructureNamespace = "PaymentAuthorization.Infrastructure";

    // Technical (I/O, networking, persistence, serialization) namespaces that business code must not touch.
    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO",
        "System.Net",
        "System.Data",
        "System.Text.Json",
        "System.Diagnostics.Process",
        "Microsoft.Data",
        "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http",
    ];

    public static TheoryData<string, Assembly> BusinessAssemblies => new()
    {
        { "Domain", typeof(Money).Assembly },
        { "Application", typeof(AuthorizePayment).Assembly },
    };

    [Theory]
    [MemberData(nameof(BusinessAssemblies))]
    public void Business_code_does_not_depend_on_technical_details(string layer, Assembly assembly)
    {
        var result = Types.InAssembly(assembly)
            .ShouldNot()
            .HaveDependencyOnAny([InfrastructureNamespace, .. TechnicalNamespaces])
            .GetResult();

        Assert.True(result.IsSuccessful,
            $"{layer} has forbidden dependencies: {string.Join(", ", result.FailingTypeNames ?? [])}");
    }

    [Fact]
    public void Domain_does_not_depend_on_Application()
    {
        var result = Types.InAssembly(typeof(Money).Assembly)
            .ShouldNot()
            .HaveDependencyOn("PaymentAuthorization.Application")
            .GetResult();

        Assert.True(result.IsSuccessful, string.Join(", ", result.FailingTypeNames ?? []));
    }
}
EOF
